class Solution {
public:
    string getSmallestString(string s, int k) {
        string res = "";
        for (char ch : s) {
            int diff = ch - 'a';
            int dist = min(diff, 26 - diff);
            if (dist <= k) {
                res.push_back('a');
                k -= dist;
            } else {
                res.push_back(ch - k);
                k = 0;
            }
        }
        return res;
    }
};

class Solution {
    public String getSmallestString(String s, int k) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            int diff = ch - 'a';
            int dist = Math.min(diff, 26 - diff);
            if (dist <= k) {
                sb.append('a');
                k -= dist;
            } else {
                sb.append((char) (ch - k));
                k = 0;
            }
        }
        return sb.toString();
    }
}

var getSmallestString = function(s, k) {
    const res = [];
    for (let i = 0; i < s.length; i++) {
        const ch = s.charCodeAt(i);
        const diff = ch - 97;
        const dist = Math.min(diff, 26 - diff);
        if (dist <= k) {
            res.push('a');
            k -= dist;
        } else {
            res.push(String.fromCharCode(ch - k));
            k = 0;
        }
    }
    return res.join('');
};
